const NAME_ALIASES = {
  'Christopher Balabanick': 'Chris Balabanick',
  'Freddy Junior Rodriguez': 'Freddy Rodriguez',
  'Richard Hayes': 'Richie Hayes',
  'Owen Andrew Lennon': 'Owen Lennon',
  'Carlos Fabio Guerra': 'Carlos Guerra',
  'William Aymami': 'Billy Aymami',
  'Kenneth Doyle': 'Kenny Doyle',
  'Matthew Paccione': 'Matt Paccione',
  'John Michael Best': 'John Best',
  'Nicholas Bonomi': 'Nick Bonomi',
  'Nick George Jurios': 'Niko Jurios',
  'Paul Nicholas Benjamin': 'Paul Benjamin'
};

const NOTION_TOKEN = $env.NOTION_API_KEY_PLANNER || $env.NOTION_API_KEY || $env.NOTION_TOKEN;

const calendarData = $input.first().json;
const events = calendarData.items || [];
if (events.length === 0) return [{ json: { sessions: [] } }];

const sessions = [];
for (const event of events) {
  if (event.status === 'cancelled') continue;
  let clientName = (event.summary || '').replace(' Appointment', '').trim();
  clientName = NAME_ALIASES[clientName] || clientName;
  const start = new Date(event.start.dateTime);
  const end = new Date(event.end.dateTime);
  const fmt = (d) => { return d.toLocaleString('en-US', { timeZone: 'America/New_York', hour: 'numeric', minute: '2-digit', hour12: true }); };
  const session = { client: clientName, time: fmt(start), end: fmt(end), location: event.location||'Rockville Centre', last_note:'N/A', note_content:'' };
  const dbId = CLIENT_DB_MAP[clientName];
  if (dbId) {
    try {
      const dbResp = await this.helpers.httpRequest({ method:'POST', url:`https://api.notion.com/v1/databases/${dbId}/query`, headers:{'Authorization':`Bearer ${NOTION_TOKEN}`,'Notion-Version':'2022-06-28','Content-Type':'application/json'}, body: JSON.stringify({sorts:[{property:'Session Date',direction:'descending'}],page_size:5}) });
      const parsed = typeof dbResp === 'string' ? JSON.parse(dbResp) : dbResp;
      if (parsed.results && parsed.results.length > 0) {
        const textProp = (props, name) => {
          const prop = props[name];
          if (!prop) return '';
          if (prop.rich_text) return prop.rich_text.map(t => t.plain_text).join(' ');
          if (prop.title) return prop.title.map(t => t.plain_text).join(' ');
          if (prop.select) return prop.select.name || '';
          if (prop.date) return prop.date.start || '';
          return '';
        };
        session.previousSessionNotes = parsed.results.slice(0, 5).map((notePage) => {
          const np = notePage.properties || {};
          const title = textProp(np, 'Session Title') || textProp(np, 'Name') || 'Progress note';
          const sessionDate = textProp(np, 'Session Date');
          const summary = [
            textProp(np, 'Session Summary'),
            textProp(np, 'Clinical Observations'),
            textProp(np, 'Key Themes'),
            textProp(np, 'Treatment Goals'),
            textProp(np, 'Risk Assessment'),
            textProp(np, 'Next Session Plan') || textProp(np, 'Next Session Plans'),
          ].filter(Boolean).join(' ').slice(0, 1200);
          return {
            sessionDate,
            title,
            summary,
            themes: textProp(np, 'Key Themes') ? [textProp(np, 'Key Themes')] : [],
            goals: textProp(np, 'Treatment Goals') ? [textProp(np, 'Treatment Goals')] : [],
            risks: textProp(np, 'Risk Assessment') ? [textProp(np, 'Risk Assessment')] : [],
            nextSteps: (textProp(np, 'Next Session Plan') || textProp(np, 'Next Session Plans')) ? [textProp(np, 'Next Session Plan') || textProp(np, 'Next Session Plans')] : [],
            sourceUrl: notePage.url || '',
          };
        }).filter(note => note.summary || note.title);
        // Pick the result with the most recent date in the title (MM-DD-YYYY)
        let page = parsed.results[0];
        let bestDate = 0;
        for (const r of parsed.results) {
          const tp = r.properties||{}; const tt = tp['Session Title']||tp['Name']||tp['title'];
          if (tt && tt.title && tt.title[0]) {
            const dm = tt.title[0].plain_text.match(/(\d{1,2})-(\d{1,2})-(\d{4})/);
            if (dm) { const ts = new Date(parseInt(dm[3]),parseInt(dm[1])-1,parseInt(dm[2])).getTime(); if (ts > bestDate) { bestDate=ts; page=r; } }
          }
          // Also check Session Date property
          if (tp['Session Date'] && tp['Session Date'].date && tp['Session Date'].date.start) {
            const ts = new Date(tp['Session Date'].date.start).getTime(); if (ts > bestDate) { bestDate=ts; page=r; }
          }
        }
        const props = page.properties||{};
        if (props['Session Date'] && props['Session Date'].date) session.last_note = props['Session Date'].date.start||'N/A';
        else { const t=props['Session Title']||props['Name']||props['title']; if(t&&t.title&&t.title[0]){const m=t.title[0].plain_text.match(/(\d{1,2})-(\d{1,2})-(\d{4})/); if(m) session.last_note=`${m[1]}/${m[2]}/${m[3]}`;} }
        try {
          const blk = await this.helpers.httpRequest({ method:'GET', url:`https://api.notion.com/v1/blocks/${page.id}/children?page_size=100`, headers:{'Authorization':`Bearer ${NOTION_TOKEN}`,'Notion-Version':'2022-06-28'} });
          const bp = typeof blk === 'string' ? JSON.parse(blk) : blk;
          const tp=[]; for(const b of (bp.results||[])){const c=b[b.type]; if(c&&c.rich_text){const x=c.rich_text.map(t=>t.plain_text).join(''); if(x)tp.push(x);}} session.note_content=tp.join('\n').substring(0,3000);
        } catch(e) { session.note_content='Could not fetch page content'; }
        const gp=(p)=>{if(!props[p])return''; if(props[p].rich_text)return props[p].rich_text.map(t=>t.plain_text).join(''); if(props[p].title)return props[p].title.map(t=>t.plain_text).join(''); return'';};
        session.clinical_observations=gp('Clinical Observations'); session.key_themes=gp('Key Themes'); session.treatment_goals=gp('Treatment Goals'); session.risk_assessment=gp('Risk Assessment'); session.next_session_plans=gp('Next Session Plans');
      }
    } catch(e) { session.note_content=`Error: ${e.message}`; }
  } else { session.note_content='No Notion database found for this client.'; }
  sessions.push(session);
}
return [{json:{sessions, date: new Intl.DateTimeFormat('en-CA', { timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date())}}];

// Build the OpenRouter request body as proper JSON
const data = $input.first().json;
const sessions = data.sessions || [];

const systemPrompt = 'You are a clinical psychotherapy assistant for Jonathan Procter, Ph.D., LMHC. Generate pre-session preparation content for each client session today. For each client, produce EXACTLY this JSON structure: {"prep": "2-4 sentences: what happened last session, key themes, what to follow up on, any flags", "summary": "3-5 sentences: where the client is in their therapeutic trajectory, core patterns, what is working", "questions": ["reflective question 1", "reflective question 2", "reflective question 3"]} Questions should: follow up on specific content from last session, promote self-reflection using the client own language and metaphors, be open-ended (how/what, not yes/no), match the client therapeutic modality (ACT values language for ACT clients, etc.). Return a JSON array with one object per client, each having: client (name), prep, summary, questions. Return ONLY valid JSON, no markdown code blocks.';

const clientBlocks = sessions.map((s, i) => {
  return `CLIENT ${i+1}: ${s.client}\nLast note date: ${s.last_note}\nClinical Observations: ${s.clinical_observations || 'N/A'}\nKey Themes: ${s.key_themes || 'N/A'}\nTreatment Goals: ${s.treatment_goals || 'N/A'}\nRisk Assessment: ${s.risk_assessment || 'N/A'}\nNext Session Plans: ${s.next_session_plans || 'N/A'}\nNote Content: ${(s.note_content || 'No content available').substring(0, 1500)}`;
}).join('\n---\n');

const userPrompt = `Generate pre-session content for today's ${sessions.length} sessions:\n\n${clientBlocks}`;

const requestBody = {
  model: 'anthropic/claude-sonnet-4',
  max_tokens: 8000,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ]
};

return [{ json: { requestBody, originalData: data } }];

const openrouterResponse = $input.first().json;
const sessionData = $('Build AI Request').first().json.originalData;

let generatedContent = [];
try {
  const responseText = openrouterResponse.choices[0].message.content;
  const jsonStr = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  generatedContent = JSON.parse(jsonStr);
} catch (e) {
  generatedContent = sessionData.sessions.map(s => ({
    client: s.client,
    prep: 'Last documented session: ' + s.last_note + '. Review notes before session.',
    summary: 'Content generation failed. Assess current state broadly.',
    questions: ['How have things been since we last met?','What feels most important to talk about today?','Is there anything from last time that stayed with you?']
  }));
}

const finalSessions = sessionData.sessions.map((session, i) => {
  const content = generatedContent.find(c => c.client && c.client.toLowerCase() === session.client.toLowerCase()) || generatedContent[i] || {};
  return {
    client: session.client, time: session.time, end: session.end, location: session.location, last_note: session.last_note,
    note_content: session.note_content, clinical_observations: session.clinical_observations, key_themes: session.key_themes,
    treatment_goals: session.treatment_goals, risk_assessment: session.risk_assessment, next_session_plans: session.next_session_plans,
    previousSessionNotes: session.previousSessionNotes || [],
    prep: content.prep || 'Last note: ' + session.last_note + '. No generated prep available.',
    summary: content.summary || 'No summary available.',
    questions: content.questions || ['How have things been since we last met?','What feels most important today?','Anything from last session that stayed with you?']
  };
});

const nowUTC = new Date();
const etOpts = { timeZone: 'America/New_York' };
const etParts = new Intl.DateTimeFormat('en-US', { ...etOpts, weekday:'long', year:'numeric', month:'long', day:'numeric' }).formatToParts(nowUTC);
const getPart = (type) => etParts.find(p => p.type === type)?.value || '';
const dn = getPart('weekday');
const mn = getPart('month');
const d = parseInt(getPart('day'));
const y = parseInt(getPart('year'));
const msh = new Intl.DateTimeFormat('en-US', { ...etOpts, month:'short' }).format(nowUTC);
const janFirst = new Date(y, 0, 1);
const wk = Math.ceil(((nowUTC - janFirst) / 86400000 + janFirst.getDay() + 1) / 7);

return [{json:{
  date: sessionData.date, day_of_week: dn,
  daily_date: dn+', '+mn+' '+d+', '+y,
  daily_date_short: msh+' '+d+', '+y,
  month_name: mn, year: y, week_num: wk,
  location: finalSessions[0]?.location || 'Rockville Centre',
  sessions: finalSessions
}}];

const input = $input.first().json;
const safe = (value) => value == null ? '' : String(value).trim();
const slug = (value) => safe(value).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'client';
const questions = (session) => Array.isArray(session.questions) ? session.questions.filter(Boolean) : [];
const previousNotes = (session) => {
  if (Array.isArray(session.previousSessionNotes) && session.previousSessionNotes.length) return session.previousSessionNotes.slice(0, 5);
  if (Array.isArray(session.recentSessionNotes) && session.recentSessionNotes.length) return session.recentSessionNotes.slice(0, 5);
  if (Array.isArray(session.notionSessionNotes) && session.notionSessionNotes.length) return session.notionSessionNotes.slice(0, 5);
  const note = safe(session.note_content || session.last_note_summary);
  if (!note || note.startsWith('VERIFY CLIENT DATABASE') || note.startsWith('No Notion database found')) return [];
  return [{
    sessionDate: safe(session.last_note),
    title: 'Most recent Notion progress note',
    summary: note.slice(0, 1200),
    themes: safe(session.key_themes) ? [safe(session.key_themes)] : [],
    goals: safe(session.treatment_goals) ? [safe(session.treatment_goals)] : [],
    risks: safe(session.risk_assessment) ? [safe(session.risk_assessment)] : [],
    nextSteps: safe(session.next_session_plans) ? [safe(session.next_session_plans)] : [],
  }];
};
const rosterDate = safe(input.date) || new Intl.DateTimeFormat('en-CA', { timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const entries = (input.sessions || []).map((session, index) => {
  const client = safe(session.client || session.clientName || session.displayName);
  if (!client) return null;
  return {
    eventId: 'n8n-' + rosterDate + '-' + index + '-' + slug(client),
    clientId: 'client-' + slug(client),
    clientName: client,
    displayName: client,
    start: safe(session.time || session.start || session.startsAt),
    end: safe(session.end || session.endsAt),
    durationMinutes: 50,
    status: safe(session.status) || 'scheduled',
    notes: safe(session.location),
    summary: safe(session.summary),
    prep: safe(session.prep),
    sessionPrep: safe(session.prep),
    bestQuestions: questions(session),
    previousSessionNotes: previousNotes(session),
    contextSource: 'n8nitro-simplepractice-notion-sync',
  };
}).filter(Boolean);
return [{ json: {
  rosterDate,
  lensId: 'clinical',
  source: 'n8nitro-simplepractice-notion-sync',
  replace: true,
  updatedAt: new Date().toISOString(),
  entries,
} }];
